<script lang="ts">
 import PublicationReview from './PublicationReview.svelte';
 import type {ReaderGateway} from '$lib/features/reading/application/reader';
 import UnsavedChanges from '$lib/shared/presentation/ui/UnsavedChanges.svelte';
 import {fieldValidation} from '$lib/shared/presentation/form-validation';
 import {queueDepth,queueReturn} from '$lib/shared/presentation/queue-context';
 import {tick} from 'svelte';
 import {page} from '$app/state';
 import QueueFilters from '$lib/shared/presentation/ui/QueueFilters.svelte';
 import {onMount} from 'svelte';
 import type {Account} from '$lib/features/identity/domain/account';
 import type {PublishingGateway,Revision} from '../application/publishing';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode,noticeText} from '$lib/shared/presentation/copy';
 import {AppFailure} from '$lib/shared/domain/failure';
 import {preparationLabel} from './messages';
 import {publicationReleaseId} from '../domain/release-link';
 import SectionHeading from '$lib/shared/presentation/ui/SectionHeading.svelte';
 let {user,gateway,reader}:{user:Account|null;gateway:PublishingGateway;reader?:ReaderGateway}=$props();const {locale}=useLocale();
 let items=$state<Revision[]>([]),loading=$state(true),busy=$state(false),more=$state(false),error=$state(''),notice=$state(''),selected=$state(''),reason=$state(''),releaseLink=$state(''),withdrawReason=$state(''),published=$state(''),availabilityAction=$state('withdraw');
 let depth=$state(1),inspecting=$state<Revision|null>(null),detailLoading=$state(false);let detailGeneration=0;let rejectDialog:HTMLDialogElement;
 async function openReview(id:string){if(guard&&!guard.confirmDiscard())return;const run=++detailGeneration;detailLoading=true;error='';try{const result=await gateway.revision(id);if(run===detailGeneration){inspecting=result;selected='';reason='';}}catch(e){if(run===detailGeneration)error=failureCode(e);}finally{if(run===detailGeneration)detailLoading=false;}}
 function backToQueue(){if(guard&&!guard.confirmDiscard())return;detailGeneration++;inspecting=null;selected='';reason='';rejectDialog?.close();}
 function requestReturn(){if(!inspecting)return;selected=inspecting.id;reason='';rejectDialog.showModal();}

 let guard=$state<{confirmDiscard():boolean}>();
 const dirty=$derived(reason.trim()!==''||withdrawReason.trim()!==''||releaseLink.trim()!=='');
 const allowed=$derived(user?.role==='admin'||user?.role==='moderator');
 async function load(append=false){const batch=await gateway.pending(append?items.length:0,page.url.searchParams.get('team')||'',page.url.searchParams.get('kind')||'');items=append?[...items,...batch]:batch;more=batch.length===100;if(append)depth++;else depth=1;}
 async function run(action:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await action();}catch(failure){error=failureCode(failure);}finally{busy=false;}}
 onMount(()=>{if(!allowed){loading=false;return;}void run(async()=>{try{await load();const wanted=queueDepth(page.url);for(let step=1;step<wanted&&more;step++)await load(true);const requested=page.url.searchParams.get('revision');if(requested)await openReview(requested);await tick();if(page.url.hash)document.getElementById(page.url.hash.slice(1))?.scrollIntoView();}finally{loading=false;}});return()=>{detailGeneration++;};});
 async function review(item:Revision,decision:'publish'|'reject'){if(decision==='publish'&&reason.trim()&&guard&&!guard.confirmDiscard())return;await run(async()=>{await gateway.review(item.id,decision,decision==='reject'?reason:'');selected='';reason='';items=items.filter(value=>value.id!==item.id);rejectDialog?.close();if(inspecting?.id===item.id){inspecting=null;if(decision==='publish'&&items[0])await openReview(items[0].id);}if(decision==='publish'){published=item.releaseId;notice=text($locale,'Тарау жарияланды.','Глава опубликована.');}else{published='';notice=text($locale,'Тарау себеппен қайтарылды.','Глава возвращена с причиной.');}});}
 async function withdraw(event:SubmitEvent){event.preventDefault();await run(async()=>{const releaseId=publicationReleaseId(releaseLink,window.location.origin);if(!releaseId)throw new AppFailure('validation');if(availabilityAction==='restore')await gateway.restore(releaseId,withdrawReason);else await gateway.withdraw(releaseId,withdrawReason);releaseLink='';withdrawReason='';notice=availabilityAction==='restore'?text($locale,'Жарияланым қайта ашылды.','Доступ к публикации восстановлен.'):text($locale,'Жарияланым оқудан алынды.','Публикация снята с чтения.');});}
</script>
<UnsavedChanges {dirty} bind:this={guard}/>
<svelte:head><title>{text($locale,'Жарияланымдарды тексеру','Проверка публикаций')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
{#if !inspecting}<SectionHeading level={1} title={text($locale,'Жарияланымдар','Публикации')} description={text($locale,'Читалкада тексер, деректерін салыстыр, содан кейін шешім қабылда.','Проверь главу в читалке и её сведения, затем прими решение.')}/>{/if}
{#if !allowed}<p>{text($locale,'Модератор рұқсаты қажет.','Нужен доступ модератора.')}</p>{:else}
 {#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{/if}
 {#if notice}<p role="status" class="form-message success">{notice}</p>{#if published}<a class="button subtle" href={'/read/'+published}>{text($locale,'Жарияланған тарауды ашу','Открыть опубликованную главу')}</a>{/if}{/if}
 {#if detailLoading}<p role="status">{text($locale,'Нұсқа жүктелуде…','Загружаем версию…')}</p>{/if}
 {#if inspecting}<PublicationReview item={inspecting} {reader} busy={busy||detailLoading} onback={backToQueue} onpublish={()=>{if(inspecting)void review(inspecting,'publish');}} onreject={requestReturn}/>{/if}
 <div class:review-hidden={!!inspecting}>
 <QueueFilters kinds={[{value:'manual',kk:'Қолмен',ru:'Вручную'},{value:'machine_assisted',kk:'Машина көмегімен',ru:'С помощью машины'},{value:'machine',kk:'Машиналық',ru:'Машинный'},{value:'unspecified',kk:'Көрсетілмеген',ru:'Не указан'}]}/>
 {#if loading}<p role="status">{text($locale,'Жарияланымдар жүктелуде…','Загружаем публикации…')}</p>{:else}
 {#each items as item}<article id={'queue-'+item.id}><div class="heading"><div><h2>{item.titleName}</h2><p class="muted">{text($locale,item.chapterLabel+'-тарау','Глава '+item.chapterLabel)} · {item.teamName}</p></div><a class="button subtle" href={'/read/'+item.releaseId+'?preview='+item.id+'&returnTo='+encodeURIComponent(queueReturn(page.url,depth,item.id))}>{text($locale,'Тексеріп оқу','Проверить в читалке')}</a></div>
 <details><summary>{text($locale,'Дереккөз, кредиттер және құқықтар','Источник, кредиты и права')}</summary><dl><dt>{text($locale,'Дереккөз және құқық негізі','Источник и основание прав')}</dt><dd>{item.source||'—'}</dd><dt>{text($locale,'Кредиттер','Кредиты')}</dt><dd>{item.credits||'—'}</dd><dt>{text($locale,'Дайындау тәсілі','Способ подготовки')}</dt><dd>{preparationLabel($locale,item.preparationMethod)}</dd><dt>{text($locale,'Команданың тексеру мәлімдемесі','Заявление команды о проверке')}</dt><dd>{item.humanReviewed?text($locale,'Адам тексерген','Проверено человеком'):text($locale,'Көрсетілмеген','Не заявлено')}{#if item.humanReviewed&&item.humanReviewer} · {item.humanReviewer}{/if}{#if item.humanReviewed&&item.humanReviewedAt} · {new Date(item.humanReviewedAt).toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ')}{/if}</dd><dt>{text($locale,'Растау','Подтверждение')}</dt><dd>{item.rightsConfirmed?text($locale,'Расталған','Подтверждено'):text($locale,'Расталмаған — жариялауға болмайды','Не подтверждено — публикация запрещена')}</dd></dl></details>
 <div class="actions"><button class="button primary" disabled={busy||detailLoading} onclick={()=>void openReview(item.id)}>{text($locale,'Нұсқаны тексеру','Проверить версию')}</button><button class="button subtle" disabled={busy} onclick={()=>{if(guard&&!guard.confirmDiscard())return;selected=item.id;reason='';}}>{text($locale,'Түзетуге қайтару','Вернуть на исправление')}</button></div>
 {#if selected===item.id}<form use:fieldValidation={{locale:$locale}} onsubmit={event=>{event.preventDefault();void review(item,'reject');}}><label>{text($locale,'Не түзету керек?','Что нужно исправить?')}<textarea bind:value={reason} required minlength="8" maxlength="2000" rows="3"></textarea></label><div class="actions"><button class="button primary" disabled={busy}>{text($locale,'Себеппен қайтару','Вернуть с причиной')}</button><button type="button" class="button subtle" onclick={()=>{if(guard&&!guard.confirmDiscard())return;selected='';reason='';}}>{text($locale,'Бас тарту','Отмена')}</button></div></form>{/if}
 </article>{:else}{#if !error}<div class="empty-state"><h2>{text($locale,'Тексерілетін тарау жоқ','Нет глав на проверке')}</h2><p>{text($locale,'Командалар жіберген дайын нұсқалар осында пайда болады.','Здесь появятся готовые версии, отправленные командами.')}</p></div>{/if}{/each}
 {#if more}<button class="button subtle" disabled={busy} onclick={()=>run(()=>load(true))}>{text($locale,'Тағы жарияланымдар','Ещё публикации')}</button>{/if}
 {/if}
 </div>
 <details class="withdraw"><summary>{text($locale,'Оқуға қолжетімділікті өзгерту','Изменить доступность для чтения')}</summary><p class="muted">{text($locale,'Нұсқа өзгермейді. Әр әрекет себеппен журналға жазылады.','Версия не изменяется. Каждое действие записывается в журнал с причиной.')}</p><form use:fieldValidation={{locale:$locale}} onsubmit={withdraw}><label>{text($locale,'Әрекет','Действие')}<select bind:value={availabilityAction}><option value="withdraw">{text($locale,'Оқудан алу','Снять с чтения')}</option><option value="restore">{text($locale,'Қолжетімділікті қалпына келтіру','Восстановить доступ')}</option></select></label><label>{text($locale,'Осы сайттағы тарау сілтемесі','Ссылка на главу этого сайта')}<input bind:value={releaseLink} required placeholder="/read/…"/></label><label>{text($locale,'Өзгерту себебі','Причина изменения')}<textarea bind:value={withdrawReason} required minlength="8" maxlength="2000" rows="3"></textarea></label><button class="button subtle" disabled={busy}>{text($locale,'Қолжетімділікті өзгерту','Изменить доступность')}</button></form></details>
{/if}
<dialog bind:this={rejectDialog} class="decision-dialog" aria-labelledby="return-review-title" oncancel={event=>{if(busy){event.preventDefault();return;}if(guard&&!guard.confirmDiscard()){event.preventDefault();return;}reason='';selected='';}}><h2 id="return-review-title">{text($locale,'Түзетуге қайтару','Вернуть на исправление')}</h2><p>{inspecting?.titleName} · {inspecting?.teamName}</p><form use:fieldValidation={{locale:$locale}} onsubmit={event=>{event.preventDefault();if(inspecting)void review(inspecting,'reject');}}><label>{text($locale,'Не түзету керек?','Что нужно исправить?')}<textarea bind:value={reason} required minlength="8" maxlength="2000" rows="4"></textarea></label>{#if error}<p role="alert">{noticeText($locale,error)}</p>{/if}<div class="actions"><button type="button" class="button subtle" disabled={busy} onclick={()=>{if(guard&&!guard.confirmDiscard())return;reason='';selected='';rejectDialog.close();}}>{text($locale,'Бас тарту','Отмена')}</button><button class="button primary" disabled={busy}>{text($locale,'Себеппен қайтару','Вернуть с причиной')}</button></div></form></dialog>
<style>article{max-width:940px;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--panel);margin-block:12px;min-width:0}.heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.heading>div{min-width:0}h2{font-size:20px;margin:0;overflow-wrap:anywhere}.muted{font-size:14px;color:var(--muted);line-height:1.6}details{max-width:800px}summary{min-height:48px;display:flex;align-items:center;cursor:pointer;font-size:14px}dt{font-size:13px;color:var(--muted)}dd{margin:8px 0 16px;white-space:pre-wrap;overflow-wrap:anywhere}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}form{display:grid;gap:16px;max-width:640px;margin:20px 0}label{display:grid;gap:8px;font-size:14px}form>.button{justify-self:start}.withdraw{margin-top:32px;border-top:1px solid var(--line);padding-top:8px}.review-hidden{display:none}.decision-dialog{max-width:560px;width:calc(100% - 32px);padding:24px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text)}.decision-dialog::backdrop{background:#0009}.decision-dialog h2{font-size:20px}.decision-dialog p{font-size:13px;color:var(--muted);margin:8px 0 16px}@media(min-width:760px){article{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;max-width:none;border:0;border-bottom:1px solid var(--line);border-radius:0;background:none;margin:0;padding:16px 20px}article .heading{display:contents}article .heading h2{font-size:15px}article>details{grid-column:1/-1}article>.actions{grid-column:1/-1;margin-top:0}article>form{grid-column:1/-1}} </style>
